7	export function isValidIsbn10(raw) {
8	  const s = normalise(raw);
9	  if (!/^\d{9}[\dX]$/.test(s)) return false;
10	  let sum = 0;
11	  for (let i = 0; i < 10; i++) sum += (10 - i) * parseInt(s[i], 10);
12	  return sum % 11 === 0;
13	}
