15	export function isValidIsbn13(raw) {
16	  const s = normalise(raw);
17	  if (!/^\d{13}$/.test(s)) return false;
18	  let sum = 0;
19	  for (let i = 0; i < 13; i++) sum += (i % 2 === 0 ? 1 : 3) * Number(s[i]);
20	  return sum % 10 === 0;
21	}
22	
23	export function toIsbn13(raw) {
24	  const s = normalise(raw);
25	  if (!isValidIsbn10(s)) throw new Error(`not a valid ISBN-10: ${raw}`);
26	  const body = "978" + s.slice(0, 9);
27	  let sum = 0;
28	  for (let i = 0; i < 12; i++) sum += (i % 2 === 0 ? 1 : 3) * Number(body[i]);
29	  return body + ((10 - (sum % 10)) % 10);
30	}
31	
32	export function parseIsbn(raw) {
33	  const s = normalise(raw);
34	  if (s.length === 10) {
35	    if (!isValidIsbn10(s)) throw new Error(`bad ISBN-10: ${raw}`);
36	    return { kind: "isbn10", value: s, isbn13: toIsbn13(s) };
37	  }
38	  if (s.length === 13) {
39	    if (!isValidIsbn13(s)) throw new Error(`bad ISBN-13: ${raw}`);
40	    return { kind: "isbn13", value: s, isbn13: s };
41	  }
42	  throw new Error(`not an ISBN: ${raw}`);
